          }
        },
        {
          "tool_name": "pwsh__wait_for_completion",
          "description": "Wait for busy console(s) to complete and retrieve cached results. Use this after receiving 'Pipeline is still running' response instead of executing Start-Sleep (which would open a new console).",
          "score": 4.033098220825195,
          "input_schema": {
            "type": "object",
            "properties": {
              "timeout_seconds": {
                "description": "Maximum seconds to wait for completion (default: 30). Automatically capped to what the connected MCP client is known to wait for. Returns early if a console completes.",
